{
  "secrets": {
    "aws_access_key": {
      "pattern": "AKIA[0-9A-Z]{16}",
      "severity": "critical",
      "description": "AWS Access Key ID"
    },
    "aws_secret_key": {
      "pattern": "[A-Za-z0-9/+=]{40}",
      "severity": "critical",
      "description": "AWS Secret Access Key (when near access key)"
    },
    "openai_api_key": {
      "pattern": "sk-[A-Za-z0-9]{20,}",
      "severity": "high",
      "description": "OpenAI API Key"
    },
    "github_token": {
      "pattern": "(ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9]{36}",
      "severity": "high",
      "description": "GitHub Personal/OAuth/Server Token"
    },
    "github_pat": {
      "pattern": "github_pat_[A-Za-z0-9_]{22,}",
      "severity": "high",
      "description": "GitHub Fine-grained PAT"
    },
    "slack_token": {
      "pattern": "xox[bpoas]-[A-Za-z0-9-]+",
      "severity": "high",
      "description": "Slack Token"
    },
    "slack_webhook": {
      "pattern": "https://hooks.slack.com/services/T[A-Z0-9]+/B[A-Z0-9]+/[A-Za-z0-9]+",
      "severity": "medium",
      "description": "Slack Webhook URL"
    },
    "stripe_live_key": {
      "pattern": "sk_live_[A-Za-z0-9]{24,}",
      "severity": "critical",
      "description": "Stripe Live Secret Key"
    },
    "stripe_publishable_key": {
      "pattern": "pk_live_[A-Za-z0-9]{24,}",
      "severity": "medium",
      "description": "Stripe Live Publishable Key"
    },
    "twilio_auth_token": {
      "pattern": "[A-Fa-f0-9]{32}",
      "severity": "high",
      "description": "Twilio Auth Token (when near twilio context)"
    },
    "sendgrid_api_key": {
      "pattern": "SG\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+",
      "severity": "high",
      "description": "SendGrid API Key"
    },
    "mailgun_api_key": {
      "pattern": "key-[A-Za-z0-9]{32}",
      "severity": "high",
      "description": "Mailgun API Key"
    },
    "private_key": {
      "pattern": "-----BEGIN (RSA |DSA |EC |OPENSSH )?PRIVATE KEY-----",
      "severity": "critical",
      "description": "Private Key"
    },
    "jwt_token": {
      "pattern": "eyJ[A-Za-z0-9_-]*\\.eyJ[A-Za-z0-9_-]*\\.[A-Za-z0-9_-]*",
      "severity": "medium",
      "description": "JWT Token"
    },
    "mongodb_uri": {
      "pattern": "mongodb(\\+srv)?://[^:]+:[^@]+@[^/]+",
      "severity": "critical",
      "description": "MongoDB Connection String with credentials"
    },
    "mysql_uri": {
      "pattern": "mysql://[^:]+:[^@]+@[^/]+",
      "severity": "critical",
      "description": "MySQL Connection String with credentials"
    },
    "postgres_uri": {
      "pattern": "postgres(ql)?://[^:]+:[^@]+@[^/]+",
      "severity": "critical",
      "description": "PostgreSQL Connection String with credentials"
    },
    "redis_uri": {
      "pattern": "redis://[^:]*:[^@]+@[^/]+",
      "severity": "high",
      "description": "Redis Connection String with password"
    },
    "google_api_key": {
      "pattern": "AIza[A-Za-z0-9_-]{35}",
      "severity": "high",
      "description": "Google API Key"
    },
    "google_oauth_client": {
      "pattern": "[0-9]+-[A-Za-z0-9_]{32}\\.apps\\.googleusercontent\\.com",
      "severity": "high",
      "description": "Google OAuth Client ID"
    },
    "azure_key": {
      "pattern": "[A-Za-z0-9]{32}",
      "severity": "medium",
      "description": "Azure Subscription Key (when near azure context)"
    },
    "heroku_api_key": {
      "pattern": "[A-Za-z0-9-]{36}",
      "severity": "high",
      "description": "Heroku API Key (when near heroku context)"
    },
    "discord_token": {
      "pattern": "[A-Za-z0-9]{24}\\.[A-Za-z0-9]{6}\\.[A-Za-z0-9_-]{27}",
      "severity": "high",
      "description": "Discord Bot Token"
    },
    "discord_webhook": {
      "pattern": "https://discord\\.com/api/webhooks/[0-9]+/[A-Za-z0-9_-]+",
      "severity": "medium",
      "description": "Discord Webhook URL"
    },
    "pypi_token": {
      "pattern": "pypi-[A-Za-z0-9_-]{50,}",
      "severity": "high",
      "description": "PyPI API Token"
    },
    "npm_token": {
      "pattern": "npm_[A-Za-z0-9]{36}",
      "severity": "high",
      "description": "npm Access Token"
    },
    "gitlab_token": {
      "pattern": "glpat-[A-Za-z0-9_-]{20}",
      "severity": "high",
      "description": "GitLab Personal Access Token"
    },
    "ethereum_private_key": {
      "pattern": "[a-fA-F0-9]{64}",
      "severity": "critical",
      "description": "Potential Ethereum Private Key (64 hex chars) - verify context"
    },
    "solana_private_key_array": {
      "pattern": "\\[\\s*[0-9]{1,3}(,\\s*[0-9]{1,3}){63,}\\s*\\]",
      "severity": "critical",
      "description": "Potential Solana Private Key (uint8 array format)"
    },
    "bitcoin_private_key": {
      "pattern": "[5KL][1-9A-HJ-NP-Za-km-z]{50,51}",
      "severity": "critical",
      "description": "Potential Bitcoin Private Key (WIF format)"
    },
    "tron_private_key": {
      "pattern": "[a-fA-F0-9]{64}",
      "severity": "critical",
      "description": "Potential TRON Private Key (64 hex chars)"
    },
    "wallet_mnemonic_12": {
      "pattern": "(mnemonic|seed|recovery|phrase)\\s*[:=]\\s*['\"]([a-z]+\\s+){10}[a-z]+['\"]",
      "severity": "critical",
      "description": "Potential 12-word mnemonic phrase assignment"
    },
    "wallet_mnemonic_24": {
      "pattern": "(mnemonic|seed|recovery|phrase)\\s*[:=]\\s*['\"]([a-z]+\\s+){22}[a-z]+['\"]",
      "severity": "critical",
      "description": "Potential 24-word mnemonic phrase assignment"
    },
    "algorand_mnemonic": {
      "pattern": "([A-Z0-9]+\\s+){24}[A-Z0-9]+",
      "severity": "critical",
      "description": "Potential Algorand 25-word mnemonic"
    },
    "polkadot_seed": {
      "pattern": "0x[a-fA-F0-9]{64}",
      "severity": "critical",
      "description": "Potential Polkadot/Substrate seed (hex format)"
    },
    "near_private_key": {
      "pattern": "ed25519:[a-zA-Z0-9+/]{43,44}",
      "severity": "critical",
      "description": "NEAR Protocol Private Key"
    },
    "aptos_private_key": {
      "pattern": "0x[a-fA-F0-9]{64,128}",
      "severity": "critical",
      "description": "Potential Aptos/Sui Private Key"
    },
    "cosmos_mnemonic": {
      "pattern": "([a-z]+\\s+){23}[a-z]+",
      "severity": "critical",
      "description": "Potential Cosmos 24-word mnemonic"
    },
    "infura_project_id": {
      "pattern": "[a-fA-F0-9]{32}",
      "severity": "medium",
      "description": "Infura Project ID (when near infura context)"
    },
    "alchemy_api_key": {
      "pattern": "[a-zA-Z0-9_-]{32}",
      "severity": "medium",
      "description": "Alchemy API Key (when near alchemy context)"
    },
    "moralis_api_key": {
      "pattern": "[a-zA-Z0-9]{32}",
      "severity": "high",
      "description": "Moralis API Key"
    },
    "quicknode_endpoint": {
      "pattern": "https://[a-z0-9-]+\\.[a-z]+\\.quiknode\\.pro/[a-zA-Z0-9]+",
      "severity": "high",
      "description": "QuickNode RPC Endpoint URL"
    },
    "coinbase_api_key": {
      "pattern": "[a-fA-F0-9]{32,64}",
      "severity": "critical",
      "description": "Coinbase API Key/Secret (when near coinbase context)"
    },
    "binance_api_key": {
      "pattern": "[a-zA-Z0-9]{64}",
      "severity": "critical",
      "description": "Binance API Key"
    },
    "kraken_api_key": {
      "pattern": "[a-zA-Z0-9+/]{56}",
      "severity": "critical",
      "description": "Kraken API Key"
    },
    "ftx_api_key": {
      "pattern": "[a-zA-Z0-9_-]{32}",
      "severity": "high",
      "description": "FTX API Key"
    }
  },
  "owasp": {
    "sql_injection": {
      "patterns": [
        "query\\s*\\(\\s*['\"`].*\\$\\{",
        "query\\s*\\(\\s*['\"`].*\\+.*\\+",
        "execute\\s*\\(\\s*['\"`].*\\$\\{",
        "\\.raw\\s*\\(\\s*['\"`].*\\$\\{",
        "\\$queryRaw.*\\$\\{",
        "cursor\\s*=\\s*['\"`].*\\+"
      ],
      "severity": "critical"
    },
    "command_injection": {
      "patterns": [
        "exec\\s*\\(\\s*['\"`].*\\$\\{",
        "exec\\s*\\(\\s*['\"`].*\\+",
        "spawn\\s*\\(\\s*['\"`].*\\$\\{",
        "system\\s*\\(\\s*['\"`]",
        "subprocess\\.call\\s*\\(\\s*['\"`]",
        "os\\.system\\s*\\("
      ],
      "severity": "critical"
    },
    "xss": {
      "patterns": [
        "dangerouslySetInnerHTML",
        "innerHTML\\s*=",
        "v-html\\s*=",
        "document\\.write",
        "document\\.writeln"
      ],
      "severity": "high"
    },
    "weak_crypto": {
      "patterns": [
        "md5\\s*\\(.*password",
        "sha1\\s*\\(.*password",
        "MD5\\s*\\(.*password",
        "SHA1\\s*\\(.*password"
      ],
      "severity": "high"
    },
    "ssl_bypass": {
      "patterns": [
        "verify\\s*=\\s*False",
        "verify\\s*=\\s*false",
        "rejectUnauthorized\\s*:\\s*false",
        "InsecureSkipVerify\\s*:\\s*true",
        "NODE_TLS_REJECT_UNAUTHORIZED\\s*=\\s*0"
      ],
      "severity": "high"
    },
    "cors_wildcard": {
      "patterns": [
        "Access-Control-Allow-Origin\\s*:\\s*\\*",
        "cors\\s*\\(\\s*\\{\\s*origin\\s*:\\s*\\*",
        "origin\\s*:\\s*['\"]\\*['\"]"
      ],
      "severity": "medium"
    },
    "debug_mode": {
      "patterns": [
        "DEBUG\\s*=\\s*[Tt]rue",
        "debug\\s*:\\s*[Tt]rue",
        "NODE_ENV\\s*=\\s*['\"]development['\"]"
      ],
      "severity": "medium"
    }
  },
  "exclusions": {
    "paths": [
      "node_modules",
      ".git",
      "__pycache__",
      "vendor",
      "dist",
      "build",
      ".next",
      "coverage"
    ],
    "file_patterns": [
      "*.test.*",
      "*.spec.*",
      "*.mock.*",
      "*_test.*",
      "*_spec.*",
      "test/*",
      "tests/*",
      "__tests__/*"
    ],
    "content_patterns": [
      "placeholder",
      "example",
      "your_",
      "YOUR_",
      "xxxx",
      "XXXX",
      "changeme",
      "dummy",
      "sample"
    ]
  }
}
